/* One escape path for every panel; dismissing UI never removes the globe. */
(()=>{let closing=false;
function hide(el){if(!el)return;el.components?.['xr-nav-drag']?.end(true);el.setAttribute('visible',false);if(el.object3D)el.object3D.visible=false;for(const grip of document.querySelectorAll('[data-panel-grip],[data-panel-dismiss],[data-panel-zoom],[data-panel-position]'))if(grip.__panelOwner===el){grip.setAttribute('visible',false);if(grip.object3D)grip.object3D.visible=false}}
function closeAll(hideNavigation=true){if(closing)return;closing=true;try{const xr=scene.components?.['xr-view'];xr?.restoreMaximized?.();window.globiquest.closeKaleidoscope?.();window.globiquest.artPlay?.stop();window.globiquest.globePatch?.clear?.();if(window.globiquest.parachutes?.open)window.globiquest.parachutes.close();if(typeof speechPlayer!=='undefined')speechPlayer?.stop();window.globiquest.closeTravel?.();window.globiquest.closeScope?.();if(typeof featureOpen!=='undefined'&&featureOpen)window.globiquest.closeAdventure?.();window.globiquest.closeWaterView?.();window.globiquest.stopHandLab?.();window.globiquest.setWorkspace?.('home',true);for(const id of ['regions','vocabulary','guideControls','musicControls','toolControls','featureWorkspace','destination','scopeView','artGallery','nova','novaCaption','guitarCorner','guitarCornerControls','parachuteHUD'])hide(document.getElementById(id));for(const el of document.querySelectorAll('[travel-console]'))hide(el);document.getElementById('spatialDock')?.querySelectorAll('button').forEach(button=>{button.dataset.userSelected='false'});const view=scene.components?.['xr-view'];if(view){view.weatherMenu=false;view.patchMenu=false;view.selectedButton=null;view.toolsHidden=!!hideNavigation;view.navManual=false;window.globiquest.resetPanelPlacements?.('nav');view.nav(document.getElementById('nav'));view.layout()}}finally{closing=false}}
window.globiquest.closeAllPanels=closeAll;window.globiquest.dismissPanel=el=>{if(el?.id==='nav'){const view=scene.components?.['xr-view'];view?.minimizeMenu(true);return}closeAll(false)};
const button=document.createElement('button');button.type='button';button.id='hideAllPanels';button.textContent='✕ Hide all panels';button.onclick=()=>closeAll(true);document.getElementById('spatialDock')?.append(button);window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeAll();e.preventDefault()}});for(const id of ['leftHand','rightHand'])for(const event of ['bbuttondown','ybuttondown'])document.getElementById(id)?.addEventListener(event,()=>closeAll(true));
})();
